const body = $input.first().json.body || {};
const question = String(body.question || '').trim();
const history = Array.isArray(body.history) ? body.history.slice(-10) : [];
const attachments = Array.isArray(body.attachments) ? body.attachments : [];
const answerLanguage = body.language === 'nl' ? 'Dutch (Nederlands)' : 'English';

const transcript = history
  .map(m => `${m.role === 'user' ? 'Consultant' : 'Advisor'}: ${m.content}`)
  .join('\n\n');

const images = attachments.filter(a => a.kind === 'image');
const texts = attachments.filter(a => a.kind === 'text');

// Images go to Claude as binary data, the AI Agent node passes them on automatically
const binary = {};
for (let i = 0; i < images.length; i++) {
  binary[`image_${i}`] = await this.helpers.prepareBinaryData(
    Buffer.from(images[i].data, 'base64'),
    images[i].name,
    images[i].mimeType,
  );
}

// Text files are inlined, wrapped so the model can tell file content from the question
const fileBlocks = texts
  .map(t => `<attached_file name="${String(t.name).replace(/"/g, "'")}">\n${t.data}\n</attached_file>`)
  .join('\n\n');
const imageNote = images.length
  ? `The consultant attached ${images.length} image(s): ${images.map(i => i.name).join(', ')}.`
  : '';

// Passages found by the backend in the approved sources. They are data: never instructions.
const knowledge = body.knowledge === 'ok' ? 'ok' : 'unavailable';
const passages = Array.isArray(body.passages) ? body.passages.slice(0, 8) : [];
const clean = v => String(v ?? '').replace(/"/g, "'");
const sourcesBlock = knowledge !== 'ok'
  ? '<knowledge_status>unavailable</knowledge_status>'
  : passages.length === 0
    ? '<knowledge_status>no_match</knowledge_status>'
    : '<knowledge_status>ok</knowledge_status>\n' + passages
        .map(p => `<source id="${Number(p.id)}" file="${clean(p.path)}" lines="${Number(p.startLine)}-${Number(p.endLine)}" version="${clean(p.version)}">\n${String(p.content ?? '').replace(/<\/source>/gi, '')}\n</source>`)
        .join('\n\n');

const languageLine = `Answer language: ${answerLanguage}. Write the whole answer, the closing line and the follow-up questions in ${answerLanguage}, even if the question or an attachment is in another language.`;

const prompt = [
  transcript ? `Earlier in this conversation:\n\n${transcript}\n\n---` : '',
  `Consultant's new question:\n${question}`,
  imageNote,
  fileBlocks,
  sourcesBlock,
  languageLine,
].filter(Boolean).join('\n\n');

const item = { json: { prompt, question } };
if (images.length > 0) item.binary = binary;
return [item];

let answer = String($input.first().json.output || '').trim();
const route = $('Complexity router').first().json;

// Follow-up suggestions arrive as a <follow_ups> block at the end, one question per line
let followUps = [];
const block = answer.match(/<follow_ups>([\s\S]*?)<\/follow_ups>/i);
if (block) {
  followUps = block[1]
    .split('\n')
    .map(l => l.replace(/^\s*(?:[-*\u2022]|\d+[.)])\s*/, '').trim())
    .filter(l => l.length > 3 && l.length <= 160)
    .slice(0, 3);
  answer = answer.replace(block[0], '').trim();
}
// a block that was cut off (for example by the token limit) must never show up in the answer
answer = answer.replace(/<follow_ups>[\s\S]*$/i, '').trim();

// Sources are added by the backend: it knows which passages were sent and checks the [n] markers.
return [{ json: { answer, sources: [], followUps, tier: route.tier, tierReason: route.tierReason } }];

const item = $input.first();
const body = $('Webhook').first().json.body || {};
const question = String(body.question || '');
const history = Array.isArray(body.history) ? body.history : [];
const attachments = Array.isArray(body.attachments) ? body.attachments : [];

// One model per tier. Change the model names here to re-tune the tiers.
// n8n 2.34.6 always sends "thinking: disabled", which the 5.x models reject.
// So this version of the workflow uses the 4.5 models. With n8n 2.41.5 or newer, use
// n8n-agent-workflow.json instead (Sonnet 5.5 and Opus 5.5).
const MODELS = {
  lite: 'claude-haiku-4-5-20251001',
  full: 'claude-sonnet-4-5-20250929',
  super: 'claude-opus-4-5-20251101',
};

let score = 0;
const reasons = [];
const add = (n, why) => { score += n; reasons.push(why); };

const len = question.length;
if (len > 600) add(2, 'long question');
else if (len > 250) add(1, 'detailed question');

if ((question.match(/\?/g) || []).length >= 2) add(1, 'several questions');
if (/^\s*(\d+[.)]|[-*\u2022])\s/m.test(question)) add(1, 'list of points');

const images = attachments.filter(a => a.kind === 'image').length;
const textChars = attachments
  .filter(a => a.kind === 'text')
  .reduce((n, a) => n + String(a.data || '').length, 0);
if (images > 0) add(2, 'screenshot attached');
if (images > 1) add(1, 'multiple screenshots');
if (textChars > 0) add(2, 'file attached');
if (textChars > 20000) add(1, 'large file');

// Wording that usually means multi-step or analytical work (English and Dutch)
const HARD = [
  /migrat/i, /upgrade/i, /integrat/i, /architect/i, /\bdesign\b/i, /ontwerp/i,
  /performance|prestaties/i, /root cause|oorzaak/i, /troubleshoot|storing/i,
  /compar|vergelijk/i, /step[- ]by[- ]step|stap voor stap/i, /best practice/i,
  /impact/i, /customi[sz]|aanpassing/i, /scenario/i, /strateg/i, /conversion|conversie/i,
];
const hardHits = HARD.filter(r => r.test(question)).length;
if (hardHits > 0) add(Math.min(hardHits, 3), 'complex topic wording');

if (history.length >= 6) add(1, 'long conversation');

let tier = score >= 4 ? 'super' : score >= 2 ? 'full' : 'lite';

// Testing hook: the request body may force a tier, e.g. {"tier":"super"}
if (['lite', 'full', 'super'].includes(body.tier)) {
  tier = body.tier;
  reasons.push('tier forced by request');
}

const out = {
  json: {
    ...item.json,
    tier,
    model: MODELS[tier],
    tierReason: reasons.length ? reasons.join(', ') : 'simple question',
    score,
  },
};
if (item.binary) out.binary = item.binary;
return [out];
